def run_check(main: Callable[[Cases], Awaitable[dict | None]]) -> None:
    cases = Cases()
    try:
        extra = asyncio.run(main(cases)) or {}
    except BaseException:
        cases.emit()          # what was observed, always one JSON line
        raise
    cases.emit(**extra)
